// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.IdentityHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class OwnedStringDiagnosticProducerTest {
	@Test
	void ordinaryAttachmentCloneAndPreflightDoNotFreezeOrRender() {
		AtomicInteger snapshots = new AtomicInteger();
		OwnedStringDiagnosticProducer producer = () -> {
			snapshots.incrementAndGet();
			return OwnedStringDiagnostic.builder().append("frozen").build();
		};
		SingletonSet source = new SingletonSet();
		source.setStringMetricPlannedDeferred("one", producer);
		source.setStringMetricPlannedDeferred("two", producer);
		SingletonSet ordinaryClone = source.clone();
		assertTrue(source.canDetachPlanningState((key, value) -> false));
		assertEquals(0, snapshots.get(), "ordinary attachment, clone and cache preflight are all lazy");
		assertEquals("frozen", ordinaryClone.getStringMetricPlanned("one"));
		assertSame(ordinaryClone.getStringMetricPlanned("one"), ordinaryClone.getStringMetricPlanned("two"));
		assertEquals(1, snapshots.get(), "ordinary aliases still share one deferred wrapper");
	}

	@Test
	void cacheCopyFreezesAnAliasOnlyOnceAndRetainsOnlyTheFinalData() {
		AtomicInteger snapshots = new AtomicInteger();
		OwnedStringDiagnosticProducer producer = () -> {
			snapshots.incrementAndGet();
			return OwnedStringDiagnostic.builder().append("owned:").jsonString("a\n").build();
		};
		SingletonSet source = new SingletonSet();
		source.setStringMetricPlannedDeferred("json", producer);
		source.setStringMetricPlannedDeferred("alias", producer);
		SingletonSet copy = new SingletonSet();
		assertTrue(source.copyDetachedPlanningStateTo(copy, (key, value, target) -> false));
		assertEquals(1, snapshots.get(), "one actual deferred wrapper freezes once, including both metric aliases");
		IdentityHashMap<Object, Long> memory = new IdentityHashMap<>();
		assertTrue(copy.accountDetachedPlanningState((object, bytes) -> memory.putIfAbsent(object, bytes) == null,
				(key, value, account) -> false));
		assertFalse(memory.containsKey(producer));
		assertFalse(memory.containsKey(snapshots));
		assertEquals("owned:\"a\\n\"", copy.getStringMetricPlanned("json"));
		assertSame(copy.getStringMetricPlanned("json"), copy.getStringMetricPlanned("alias"));
		assertEquals(1, snapshots.get(), "cached rendering must never return to the recipe-owning producer");
		SingletonSet another = new SingletonSet();
		assertTrue(copy.copyDetachedPlanningStateTo(another, (key, value, target) -> false));
		assertEquals(copy.getStringMetricPlanned("json"), another.getStringMetricPlanned("json"));
		assertEquals(1, snapshots.get(), "copy/emission of final data cannot re-freeze the original producer");
	}

	@Test
	void unknownSupplierIsStillRefusedWithoutInvocationEvenUnderAnEngineMetricName() {
		AtomicInteger calls = new AtomicInteger();
		SingletonSet source = new SingletonSet();
		source.setStringMetricPlannedDeferred("optimizer.packedExplanationJson", () -> {
			calls.incrementAndGet();
			return "unowned";
		});
		assertFalse(source.canDetachPlanningState((key, value) -> false));
		assertFalse(source.copyDetachedPlanningStateTo(new SingletonSet(), (key, value, target) -> false));
		assertEquals(0, calls.get());
	}
}
